// Extract error details for AI analysis
const errorData = $input.first().json;

const errorContext = {
  workflowName: errorData.workflow?.name || 'Unknown',
  workflowId: errorData.workflow?.id || 'Unknown',
  nodeName: errorData.execution?.error?.node?.name || 'Unknown',
  nodeType: errorData.execution?.error?.node?.type || 'Unknown',
  errorMessage: errorData.execution?.error?.message || 'No error message',
  errorStack: errorData.execution?.error?.stack?.substring(0, 500) || '',
  timestamp: new Date().toISOString(),
  executionId: errorData.execution?.id || 'Unknown'
};

return [{ json: errorContext }];

