// Parse AI analysis response
const input = $input.first().json;
let analysis;

try {
  // Try to parse JSON from response
  const content = input.message?.content || input.choices?.[0]?.message?.content || '{}';
  analysis = JSON.parse(content);
} catch (e) {
  analysis = {
    analysis: 'Failed to parse AI response',
    severity: 'medium',
    canAutoFix: false,
    humanActionRequired: true,
    notifyTeam: true
  };
}

return [{ json: { ...analysis, originalError: $('Extract Error Context').first().json } }];

// Prepare Slack notification
const data = $input.first().json;
const severity = data.severity || 'medium';
const severityEmoji = {
  low: 'large_yellow_circle',
  medium: 'large_orange_circle', 
  high: 'red_circle',
  critical: 'rotating_light'
};

return [{
  json: {
    channel: '#alerts',
    blocks: [
      {
        type: 'header',
        text: {
          type: 'plain_text',
          text: `Workflow Error: ${data.originalError?.workflowName || 'Unknown'}`
        }
      },
      {
        type: 'section',
        fields: [
          { type: 'mrkdwn', text: `*Severity:* :${severityEmoji[severity]}: ${severity.toUpperCase()}` },
          { type: 'mrkdwn', text: `*Node:* ${data.originalError?.nodeName || 'Unknown'}` }
        ]
      },
      {
        type: 'section',
        text: { type: 'mrkdwn', text: `*Analysis:*\n${data.analysis || 'No analysis available'}` }
      },
      {
        type: 'section',
        text: { type: 'mrkdwn', text: `*Suggested Fix:*\n${data.suggestedFix || 'Manual investigation required'}` }
      }
    ]
  }
}];

// Log error for monitoring
const data = $input.first().json;

console.log('Error handled without notification:', JSON.stringify(data, null, 2));

return [{
  json: {
    status: 'logged',
    severity: data.severity,
    autoFixed: data.canAutoFix,
    timestamp: new Date().toISOString()
  }
}];
